-- Read-only authorization fingerprint, excluding business rows and volatile OIDs.
select jsonb_build_object(
 'capabilities',(select jsonb_agg(jsonb_build_array(role,capability) order by role,capability) from public.app_role_capabilities where capability in ('viewIntake','accessIntake','createProductionJob','scheduleProduction','manageUsers')),
 'functions',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'body',md5(regexp_replace(pg_get_functiondef(p.oid),'\s','','g')),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl,'security_definer',p.prosecdef,'config',p.proconfig) order by p.oid::regprocedure::text collate "C") from pg_proc p where p.pronamespace='public'::regnamespace and p.prokind='f' and (p.proname like '%bid%' or p.proname like '%intake%' or p.proname like '%training%' or p.proname in ('has_app_capability','require_app_capability','admin_permanently_delete_production_job','prepare_admin_delete_production_job','production_job_delete_blockers'))),
 'tables',(select jsonb_agg(jsonb_build_object('name',n.nspname||'.'||c.relname,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'columns',case when n.nspname='storage' then null else (select jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attacl) order by a.attnum) from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped) end,'triggers',case when n.nspname='storage' then null else (select jsonb_agg(pg_get_triggerdef(t.oid) order by t.tgname) from pg_trigger t where t.tgrelid=c.oid and not t.tgisinternal) end,'constraints',case when n.nspname='storage' then null else (select jsonb_agg(jsonb_build_array(conname,pg_get_constraintdef(co.oid)) order by conname) from pg_constraint co where co.conrelid=c.oid) end) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r' and ((n.nspname='public' and c.relname in ('bids','bid_updates','bid_activity','bid_file_relationships','bid_proposal_relationships','canonical_files','jobs','intake_training_workflows','intake_training_grants')) or (n.nspname='storage' and c.relname='objects'))),
 'policies',(select jsonb_agg(to_jsonb(p) order by schemaname,tablename,policyname) from pg_policies p where (schemaname='public' and tablename in ('bids','bid_updates','bid_activity','bid_file_relationships','bid_proposal_relationships','canonical_files','jobs','intake_training_workflows','intake_training_grants')) or (schemaname='storage' and tablename='objects'))
) as contract
